struct SynthMavenEditor::Style:LookAndFeel_V4{
 Style(){setColour(TextButton::buttonColourId,panelColour);setColour(TextButton::textColourOffId,muted);setColour(TextButton::textColourOnId,accent);setColour(TextButton::buttonOnColourId,Colour(0xff253d40));setColour(ComboBox::backgroundColourId,panelColour);setColour(ComboBox::outlineColourId,line);setColour(ComboBox::textColourId,ink);setColour(PopupMenu::backgroundColourId,panelColour);setColour(PopupMenu::textColourId,ink);setColour(ListBox::backgroundColourId,bg);setColour(TextEditor::backgroundColourId,panelColour);setColour(TextEditor::textColourId,ink);setColour(TextEditor::outlineColourId,line);setColour(Slider::textBoxTextColourId,ink);setColour(Slider::textBoxOutlineColourId,Colours::transparentBlack);setColour(Slider::textBoxBackgroundColourId,Colours::transparentBlack);}
 void drawRotarySlider(Graphics&g,int x,int y,int w,int h,float pos,float start,float end,Slider&)override{float r=jmin(w,h)*.5f-7,cx=x+w*.5f,cy=y+h*.5f;Path track;track.addCentredArc(cx,cy,r,r,0,start,end,true);g.setColour(line);g.strokePath(track,PathStrokeType(3));Path arc;arc.addCentredArc(cx,cy,r,r,0,start,start+pos*(end-start),true);g.setColour(accent);g.strokePath(arc,PathStrokeType(3));g.setColour(Colour(0xff222e3d));g.fillEllipse(cx-r+6,cy-r+6,2*r-12,2*r-12);float a=start+pos*(end-start);g.setColour(ink);g.drawLine(cx+std::sin(a)*(r-15),cy-std::cos(a)*(r-15),cx+std::sin(a)*(r-7),cy-std::cos(a)*(r-7),2);}
 void drawButtonBackground(Graphics&g,Button&b,const Colour&,bool over,bool)override{g.setColour(b.getToggleState()?Colour(0xff263f42):over?Colour(0xff283544):panelColour);g.fillRoundedRectangle(b.getLocalBounds().toFloat(),5);if(b.getToggleState()){g.setColour(accent);g.fillRect(8,b.getHeight()-2,b.getWidth()-16,2);}}
};
struct SynthMavenEditor::Control:Component{
 SynthMavenProcessor&p;int index,layer;String id;Label label;Slider knob;ComboBox choices;bool choice=false;std::unique_ptr<AudioProcessorValueTreeState::SliderAttachment> attachment;
 Control(SynthMavenProcessor&proc,int i,int target=-1):p(proc),index(i),layer(target<0?proc.selectedLayer.load():target),id(proc.parameterId(i,layer)){addAndMakeVisible(label);String title=p.parameterLabel(i,layer);if(i==1)title="ATTACK";if(i==2)title="DECAY";if(i==3)title="SUSTAIN";if(i==4)title="RELEASE";if(i==37)title="VOICE MODE";if(i==38)title="PORTAMENTO TIME";if(i==41)title="PORTAMENTO MODE";if(i==96)title="BRIGHTNESS";if(i==97)title="TIMBRE";if(i==98)title="MOTION";label.setText(title,dontSendNotification);label.setJustificationType(Justification::centred);label.setColour(Label::textColourId,muted);label.setFont(Font(11,Font::bold));addAndMakeVisible(knob);knob.setSliderStyle(Slider::RotaryHorizontalVerticalDrag);knob.setTextBoxStyle(Slider::TextBoxBelow,false,94,18);knob.setRange(0,1);knob.setDoubleClickReturnValue(true,sm_get_parameter_default());knob.textFromValueFunction=[this](double v){return p.parameterText(index,(float)v,layer);};knob.setPopupDisplayEnabled(false,false,this);auto d=sm_parameter_info(p.selectedEngine(layer),i);choice=d.choices!=0;if(choice){knob.setVisible(false);addAndMakeVisible(choices);for(int v=d.minimum;v<=d.maximum;v++)choices.addItem(sm_parameter_choice(p.selectedEngine(layer),i,v),v-d.minimum+1);choices.onChange=[this]{auto*param=p.parameters.getParameter(id);param->beginChangeGesture();param->setValueNotifyingHost((float)choices.getSelectedItemIndex()/jmax(1,choices.getNumItems()-1));param->endChangeGesture();};refresh();}else attachment=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.parameters,id,knob);knob.textFromValueFunction=[this](double v){return p.parameterText(index,(float)v,layer);};knob.setColour(Slider::textBoxOutlineColourId,Colours::transparentBlack);knob.setTextBoxIsEditable(false);knob.updateText();setTooltip();addMouseListener(this,true);}
 double sm_get_parameter_default(){auto d=sm_parameter_info(p.selectedEngine(layer),index);return d.maximum>d.minimum?(double)(d.initial-d.minimum)/(d.maximum-d.minimum):0;}
 void setTooltip(){knob.setTooltip(p.parameterLabel(index)+" / drag to edit, double-click to reset / DAW parameter "+id);}
 void mouseDown(const MouseEvent&e)override{if(!e.mods.isPopupMenu())return;PopupMenu menu;menu.addSectionHeader(p.mappingDescription(id));menu.addItem(1,"MIDI Learn");menu.addItem(2,"Remove MIDI mapping");Component::SafePointer<Control> safe(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(this),[safe](int action){if(!safe)return;if(action==1)safe->p.beginLearn(safe->id);if(action==2)safe->p.removeMapping(safe->id);});}
 void refresh(){if(choice){auto*v=p.parameters.getRawParameterValue(id);if(v)choices.setSelectedItemIndex(roundToInt(v->load()*(choices.getNumItems()-1)),dontSendNotification);}}
 void resized()override{choices.setBounds(5,40,getWidth()-10,31);label.setBounds(0,0,getWidth(),20);knob.setBounds(0,18,getWidth(),getHeight()-18);}
};
